INSERT INTO `model` VALUES (1,'Pilot Sport 3 ','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkmf28cn02eq01lmat8lqnda-tire-pilot-sport-3.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Acclaimed by leading car manufacturers and consumers. Customized as original equipment on ultra-high performance vehicles such as the Mercedes E63 AMG and Audi A5.',1),(2,'Pilot Exalto PE2','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckir9lpa50bo801oyixigt2sb-tire-pilot-exalto-pe2.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Ultra-high performance fitments for classic Porsches.',1),(3,'Pilot Sport 4 S','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckko6cbu504f101offiztcbp2-4w-240-3528706263095-tire-michelin-pilot-sport-4-s-255-slash-35-zr19-96y-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Genuine Passion. Exceptional Drives. Derived from the legendary MICHELIN® PILOT® Super Sport, there is a new #1 in max performance summer tires. The new MICHELIN® Pilot® Sport 4 S offers exceptional grip, steering precision, and control, even at high speed.',1),(4,'Pilot Sport 4','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/cknqwphql0n7901jr3n1o70es-4w-238-3528700093414-tire-michelin-pilot-sport-4-245-slash-40-zr18-97y-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','From mind to road. Instantly. Adapt to the road with precision handling with safety made to last, steering control and longevity.',1),(5,'Pilot Sport Cup 2 Connect','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkmnvye0043f01lm963q6220-4w-97-3528708422858-tire-michelin-pilot-sport-cup-2-305-slash-30-zr21-104y-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Track performance made to last. The tire that excels in faster and more consistent lap times. Compatible with Michelin® Track Connect.',1),(6,'Pilot Sport Cup 2 R','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckki6706i00qs01lrt53e6v8i-4w-97-3528702644577-tire-michelin-pilot-sport-cup-2-235-slash-35-zr19-91y-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Engineered for ultra-high performance sports vehicles, the MICHELIN® Pilot® Sport Cup 2 R track tire is the Ultimate lap time smasher.',1),(7,'Pilot Sport Cup 2','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckko8umru063s01lmzbfwjysc-4w-97-3528702644577-tire-michelin-pilot-sport-cup-2-235-slash-35-zr19-91y-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Track day after track day, make the most of your sports car—for drivers who demand high performance and precision handling on track. Developed in partnership with AMG SLS Coupe Black Series, Porsche 918 Spyder and 911 GT3, and Ferrari 458 Speciale.',1),(8,'Pilot Sport EV','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/cksuuvcr309n001itdcvnxjxd-tire-pilotev-left-one-quarter.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Electrified road control made to last',1),(9,'Pilot Sport PS2','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkm9fe4f01ec01ofys2ufwvv-ps21q.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Exceptional performance for drivers demanding precise sport handling. Original equipment on renowned sports cars like BMW M3, Porsche 911 and Chevrolet Corvette ZR1.',1),(10,'Pilot Super Sport','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkmaiz4701k601lmrvnzfve8-plt-ss1q.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Born from endurance racing, MICHELIN® Pilot® Super Sport gives you the exhilaration of driving the best performing street tire in the world.',1),(11,'Energy','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkm58a3t00ir01lmbyaxsruk-eg1q.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Outstanding wet braking ability in a fuel-efficient summer tire. Original equipment on vehicles like MINI Cooper, BMW 3 Series, and Volkswagen Passat.',1),(12,'Primacy 3','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkgmndzw06pk01madxdjo2gq-4w-105-3528704123940-tire-michelin-primacy-3-205-slash-55-r16-91v-nl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','This summer tire delivers excellent wet and dry handling and is original equipment on luxury touring vehicles like BMW 5 & 7 Series, Mercedes-Benz S-Class and Audi A6.',1),(13,'Primacy','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkm9m7ka01gj01ofmnsco1py-pmc-hp1q.png?w=190&org_if_sml=1&func=boundmin&ci_info=','This summer tire delivers precise wet and dry handling and is original equipment on luxury touring vehicles like Lexus GS 430, Mercedes-Benz E-Class and Audi A6',1),(14,'Diamaris','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkm4ipoz00c401ofbx7s1djn-4x4diam1q.png?w=190&org_if_sml=1&func=boundmin&ci_info=','High-performance SUV and Crossover tire with sport performance capabilities via excellent grip in both dry and wet road conditions.',1),(15,'Latitude Sport 3 ','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckknsc49w02ko01lmi3bmeral-4w-45-3528709223034-tire-michelin-latitude-sport-3-275-slash-40-r20-106y-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Long-lasting premium SUV and Crossover tire with ultra-high sport performance capabilities due to outstanding dry grip coupled with excellent wet grip.',1),(16,'Latitude Sport','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckiq3ithj0ean01oy8ogqf6m4-tire-latitude-sport.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Ultra high-performance SUV and Crossover tire that offers sport performance capabilities via excellent dry grip.',1),(17,'Pilot Alpin 5 SUV','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckknuksrz0alb01ox2ozxcbfp-4w-358-3528706316593-tire-michelin-pilot-alpin-5-suv-235-slash-55-r19-105v-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','MICHELIN® Pilot® Alpin® 5™ SUV tires offer control whatever the winter conditions.',1),(18,'Pilot Alpin 5','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckknt9lxd033k01lmglfi4f9g-4w-323-3528708173156-tire-michelin-pilot-alpin-5-235-slash-45-r18-98v-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','MICHELIN® Pilot® Alpin® 5™ tires offer control whatever the winter conditions.',1),(19,'Pilot Alpin PA4','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckknwrw0d0az901ox1iikl3ca-4w-74-3528700049770-tire-michelin-pilot-alpin-pa4-235-slash-55-r18-104v-xl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','Offering control and safety in winter. MICHELIN® Pilot® Alpin® PA4™ tires merge Pilot performance handling with Alpin tire winter capabilities.',1),(20,'X-ICE SNOW','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedge.net/b2c-experience-production/attachments/ckkfggxw500e601k3cps7zlab-4w-463-3528701004396-tire-michelin-x-ice-snow-205-slash-55-r16-94h-xl-tl-a-main-1-30.png?w=190&org_if_sml=1&func=boundmin&ci_info=','A winter tire designed for maximum mobility and safety–not just when it’s new, but for seasons to come.',1),(21,'X-Ice Xi3','https://aecbmesvcm.cloudimg.io/v7/https://dcadprod.azureedg