  `id` int NOT NULL AUTO_INCREMENT,
  `loudness_level` varchar(10) DEFAULT NULL,
  `price` float NOT NULL,
  `quantity` int NOT NULL,
  `load_index` int NOT NULL,
  `speed_rating` varchar(5) NOT NULL,
