  `car_type` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_tire_model_id_idx` (`model_id`),
  KEY `fk_tire_dimention_id_idx` (`dimention_id`),
  KEY `fk_tire_season_id_idx` (`season_id`),
  KEY `fk_tire_fuel_efficiency_id_idx` (`fuel_efficiency_id`),
