  KEY `fk_tire_car_type_idx` (`car_type`),
  CONSTRAINT `fk_tire_dimention_id` FOREIGN KEY (`dimention_id`) REFERENCES `dimension` (`id`),
  CONSTRAINT `fk_tire_fuel_efficiency_id` FOREIGN KEY (`fuel_efficiency_id`) REFERENCES `fuel_efficiency` (`id`),
  CONSTRAINT `fk_tire_grip_id` FOREIGN KEY (`wet_traction_rating`) REFERENCES `grip` (`id`),
  CONSTRAINT `fk_tire_model_id` FOREIGN KEY (`model_id`) REFERENCES `model` (`id`),
  CONSTRAINT `fk_tire_season_id` FOREIGN KEY (`season_id`) REFERENCES `season` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6165 DEFAULT CHARSET=utf8mb3;
